<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();$orgId=saas_require_organization();$tourId=saas_require_tour();saas_require_permission('passenger.create');$db=saas_db();$tour=saas_current_tour();$org=saas_current_organization();
$q=$db->prepare("SELECT ti.id,ti.ticket_number,ti.status,ti.issued_at,ti.tour_passenger_id,pp.full_name,pp.phone FROM ticket_instances ti JOIN tour_passengers tp ON tp.id=ti.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE ti.tour_id=? AND ti.organization_id=? ORDER BY ti.id DESC");$q->execute([$tourId,$orgId]);$rows=$q->fetchAll();$issued=0;foreach($rows as $r)if($r['status']==='ISSUED')$issued++;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tickets — <?=saas_h($tour['name'])?> — GoTM</title><style>.ticket-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:18px}.ticket-stat{padding:16px;border:1px solid #e1eee6;border-radius:14px;background:#fff}.ticket-stat small{color:#667085}.ticket-stat strong{display:block;font-size:25px;margin-top:5px;color:#0b2a49}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:12px;border-bottom:1px solid #edf0f2;text-align:left;font-size:12px}th{font-size:10px;color:#667085;text-transform:uppercase}.actions{display:flex;gap:6px;flex-wrap:wrap}.btn{display:inline-flex;padding:8px 11px;border-radius:8px;border:1px solid #d0d5dd;background:#fff;text-decoration:none;color:#172033!important;font-weight:800;font-size:11px}.btn.primary{background:#f7ab17;border-color:#f7ab17}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#dcfae6;color:#067647;font-size:10px;font-weight:900}.badge.void{background:#fef3f2;color:#b42318}@media(max-width:600px){.ticket-stats{grid-template-columns:1fr}}</style></head><body><main class="wrap"><section class="card"><div class="head"><div><div class="eyebrow">TOUR TICKETS</div><h1>Tickets</h1><p class="muted">Issued QR tickets for <?=saas_h($tour['name'])?>.</p></div><div class="actions"><a class="btn" href="passengers.php">Passengers</a><a class="btn" href="ticket_design.php">Ticket Design</a><a class="btn primary" target="_blank" href="tickets_print_all.php">Print All Tickets</a><a class="btn" href="dashboard.php">Dashboard</a></div></div></section><section class="card" style="margin-bottom:18px"><strong>Print & Design</strong><p class="muted" style="margin:6px 0 10px">Create one reusable ticket layout, then print all issued tickets with each passenger’s live information.</p><div class="actions"><a class="btn primary" href="ticket_design.php">Open visual designer</a><a class="btn" target="_blank" href="tickets_print_all.php">Print all issued tickets</a></div></section><section class="ticket-stats"><div class="ticket-stat"><small>Total tickets</small><strong><?=count($rows)?></strong></div><div class="ticket-stat"><small>Currently issued</small><strong><?=$issued?></strong></div></section><section class="card"><div class="tablewrap"><table><thead><tr><th>Passenger</th><th>Ticket number</th><th>Issued</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5">No tickets issued yet. Open a passenger and issue a QR ticket.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=saas_h($r['full_name'])?></strong><br><span class="muted"><?=saas_h($r['phone']??'')?></span></td><td><?=saas_h($r['ticket_number'])?></td><td><?=saas_h($r['issued_at'])?></td><td><span class="badge <?=$r['status']==='ISSUED'?'':'void'?>"><?=saas_h($r['status'])?></span></td><td><div class="actions"><?php if($r['status']==='ISSUED'):?><a class="btn primary" target="_blank" href="ticket.php?ticket_id=<?=$r['id']?>">Open ticket</a><a class="btn" target="_blank" href="ticket_verify.php?ticket=<?=rawurlencode($r['ticket_number'])?>">Verify</a><?php endif;?><a class="btn" href="ticket_issue.php?passenger_id=<?=$r['tour_passenger_id']?>"><?=$r['status']==='ISSUED'?'Reissue':'Issue'?></a></div></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></body></html>